-- 서브쿼리도 넣을 수 있다

@Test
void 서브쿼리_필드() {
    QMember sub = new QMember("memberSub");
    em.clear();

    UserDto d = queryFactory
            .select(Projections.fields(UserDto.class,
                    member.username.as("name"),
                    ExpressionUtils.as(
                            JPAExpressions.select(sub.age.max()).from(sub),
                            "age")))
            .from(member)
            .where(member.username.eq("m1"))
            .fetchOne();
    System.out.println(d.getName() + " " + d.getAge());
}

